    {
        "id": "q166",
        "question": "What is the name for the organic-rich fine-grained sediment that is the precursor to petroleum source rocks?",
        "options": ["Sapropel", "Peat", "Lignite", "Kerogen"],
        "answer": "Sapropel",
        "explanation": "Sapropel is an organic-rich, dark, anoxic sediment forming in stratified water bodies where organic matter accumulates faster than it decomposes. With burial and diagenesis it forms the kerogen in organic-rich shales, the precursor to oil and gas.",
    },
    {
        "id": "q167",
        "question": "What is the Hjulström curve used for in sedimentology?",
        "options": ["To show the water velocity needed to erode, transport, or deposit sediment of different grain sizes", "To predict compaction rates", "To determine carbonate saturation", "To identify sedimentary environments"],
        "answer": "To show the water velocity needed to erode, transport, or deposit sediment of different grain sizes",
        "explanation": "The Hjulström diagram plots grain size vs. water velocity to show erosion, transport, and deposition fields. Notably, fine clay requires higher velocities to erode than sand because cohesive forces resist entrainment, but once in suspension clay settles very slowly.",
    },
    {
        "id": "q168",
        "question": "What is a 'palaeosol' in stratigraphy?",
        "options": ["An ancient soil horizon preserved in the rock record", "An ancient beach", "A fossil forest floor", "A lake bed deposit"],
        "answer": "An ancient soil horizon preserved in the rock record",
        "explanation": "Palaeosols are ancient soil horizons buried and preserved in the stratigraphic record. They indicate periods of subaerial exposure and non-deposition. Red, leached horizons with root traces and carbonate nodules are common indicators.",
    },

