    {
        "id": "q965",
        "question": "What is 'pseudomorph' in mineralogy and give an example?",
        "options": ["A mineral specimen in which one mineral has replaced another while retaining the external crystal form of the original; examples: malachite pseudomorphs after azurite (green replacing blue), quartz after fluorite (octahedral quartz), limonite after pyrite (cubic limonite), and calcite after aragonite", "A mineral that crystallises in an unusual habit not typical for its species", "A twinned crystal that mimics the symmetry of a higher-symmetry crystal class", "A rock that superficially resembles a different rock type due to metamorphic overprinting"],
        "answer": "A mineral specimen in which one mineral has replaced another while retaining the external crystal form of the original; examples: malachite pseudomorphs after azurite (green replacing blue), quartz after fluorite (octahedral quartz), limonite after pyrite (cubic limonite), and calcite after aragonite",
        "explanation": "Pseudomorphism (Greek 'false form') occurs by: replacement (atom-by-atom substitution), encrustation (new mineral coats the original), or paramorphism (composition unchanged but structure changes, e.g., aragonite → calcite). Copper pseudomorphs after aragonite (Keweenaw), fluorite pseudomorphs after calcite, and 'gossan cubes' (limonite after pyrite) are classic examples. Pseudomorphs are highly valued by collectors for their educational interest — preserving the 'ghost' of the original crystal.",
    },
