class SubmitBody(BaseModel):
    answers: dict[str, str]


@router.get("/questions")
async def get_questions(visitor: User = Depends(get_current_user)) -> list[dict]:
    selected = random.sample(_BANK, QUESTIONS_PER_SESSION)
    result = []
    for q in selected:
        options = q["options"][:]
        random.shuffle(options)
        result.append({"id": q["id"], "question": q["question"], "options": options, "answer": q["answer"], "explanation": q["explanation"]})
    return result


@router.post("/submit")
async def submit_quiz(
    body: SubmitBody,
    visitor: User = Depends(get_current_user),
) -> dict:

    bank_map = {q["id"]: q for q in _BANK}
    results = []
    correct_count = 0

    for qid, chosen in body.answers.items():
        q = bank_map.get(qid)
        if not q:
            continue
        is_correct = chosen == q["answer"]
        if is_correct:
            correct_count += 1
        results.append({
            "id": qid,
            "correct": is_correct,
            "correct_answer": q["answer"],
            "explanation": q["explanation"],
        })

    score = correct_count
    perfect = score == QUESTIONS_PER_SESSION

    # Award points only on the first submission today (UTC date)
    today_start = datetime(date.today().year, date.today().month, date.today().day, tzinfo=UTC)
    already_played_today = await QuizResult.find_one(
        QuizResult.visitor_id == visitor.id,
        QuizResult.completed_at >= today_start,
    )
    points = 0 if already_played_today else (score * POINTS_PER_CORRECT + (PERFECT_BONUS if perfect else 0))
    points_eligible = already_played_today is None

    result = QuizResult(
        visitor_id=visitor.id,
        score=score,
        max_score=QUESTIONS_PER_SESSION,
        points_awarded=points,
    )
    await result.insert()

    return {
        "score": score,
        "max_score": QUESTIONS_PER_SESSION,
        "points_awarded": points,
        "points_eligible": points_eligible,
        "perfect": perfect,
        "results": results,
    }
